  "Team title": "\u30c1\u30fc\u30e0\u540d",
  "Meetup time (your device time)": "\u96c6\u5408\u6642\u523b\uff08\u7aef\u672b\u306e\u6642\u523b\uff09",
  "Team size": "\u30c1\u30fc\u30e0\u306e\u4eba\u6570",
